import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong features based on t-statistics
    strong_features = []
    for i, fid in enumerate(feats.ids):
        # Use the actual t-statistic from feats.types if available
        t_stat = feats.types[i]

        # Handle different data types
        if isinstance(t_stat, (list, tuple)) and len(t_stat) > 0:
            t_stat = t_stat[0]  # Assume first element is t-stat
        elif isinstance(t_stat, str):
            try:
                t_stat = float(t_stat)
            except ValueError:
                continue
        elif not isinstance(t_stat, (int, float)):
            continue

        # Convert to float if needed
        try:
            t_stat = float(t_stat)
        except (ValueError, TypeError):
            continue

        if abs(t_stat) > 1.5:
            strong_features.append((fid, t_stat))

    # Sort by absolute t-statistic
    strong_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Check for product terms among top features
    top_features = [fid for fid, _ in strong_features[:10]]

    # Look for correlated pairs with |r| >= 0.6
    product_candidates = []
    correlations = {}

    # Compute correlation matrix
    corr_matrix = np.corrcoef(feats.x.T)

    # Find highly correlated pairs
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            fid1, fid2 = top_features[i], top_features[j]
            col1, col2 = feats.column(fid1), feats.column(fid2)
            if col1 < len(corr_matrix) and col2 < len(corr_matrix):
                corr = corr_matrix[col1, col2]
                if abs(corr) >= 0.6:
                    correlations[(fid1, fid2)] = corr
                    product_candidates.append((fid1, fid2))

    # If we have product candidates, try them
    if product_candidates:
        # Select the pair with highest absolute correlation
        best_pair = max(product_candidates, key=lambda p: abs(correlations[p]))
        return Design(
            drivers=(),
            columns=(best_pair[0], best_pair[1]),
            products=(best_pair,),
            loadings={}
        )

    # If no strong correlation found, return empty design
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

